.faq-answer p {
  margin: 0;
}

.faq-answer p + p {
  margin-top: 12px;
}

.faq-answer ul,
.faq-answer ol {
  margin: 12px 0;
  padding-left: 24px;
}

.faq-answer li {
  margin: 6px 0;
}

.faq-answer a {
  color: var(--accent);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s ease;
}

.faq-answer a:hover {
  border-bottom-color: var(--accent);
}
...
  .faq-answer a {
    color: LinkText;
    border-bottom-color: LinkText;
  }

/* After (src/components/FaqItem.astro:76-102, 151-156) */
.faq-answer :global(p) {
  margin: 0;
}

.faq-answer :global(p + p) {
  margin-top: 12px;
}

.faq-answer :global(ul),
.faq-answer :global(ol) {
  margin: 12px 0;
  padding-left: 24px;
}

.faq-answer :global(li) {
  margin: 6px 0;
}

.faq-answer :global(a) {
  color: var(--accent);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s ease;
}

.faq-answer :global(a:hover) {
  border-bottom-color: var(--accent);
